// Curated CEFR Level Profiles & Exam Question Bank (A1–C1)
// Covers all 36 supported locales (+ pt-br and es-mx regional aliases).

const LOCS = [
  'ar', 'bn', 'bg', 'zh', 'hr', 'cs', 'da', 'en', 'et', 'fi', 'fr', 'de',
  'el', 'hi', 'hu', 'id', 'it', 'ja', 'kk', 'ko', 'lv', 'lt', 'fa', 'pl',
  'pt', 'ro', 'ru', 'sk', 'sl', 'es', 'sv', 'th', 'tr', 'uk', 'ur', 'vi',
];

function t36(vals) {
  const out = {};
  for (let i = 0; i < LOCS.length; i++) {
    out[LOCS[i]] = vals[i];
  }
  return out;
}

export function normalizeCefrLang(lang) {
  const raw = String(lang || 'en').toLowerCase().trim();
  if (raw === 'pt-br' || raw === 'pt_br') return 'pt';
  if (raw === 'es-mx' || raw === 'es_mx') return 'es';
  const base = raw.split(/[-_]/)[0];
  return LOCS.includes(base) ? base : 'en';
}

